class PubsubMessage:
    """Represents a message for Pub/Sub, either for publishing or consuming."""
    def __init__(self, data: bytes, attributes: Optional[Dict[str, str]] = None, message_id: Optional[str] = None):
        if not isinstance(data, bytes):
